const row = $input.first().json;
const draft = row.ai_DescriptionDraft || '';

return [{
  json: {
    sys_ProjectID: row.sys_ProjectID,
    hasDraft: draft.trim().length > 0,
    draft,
  }
}];

const response = $input.first().json;
const output = response.output || [];
const messageItem = output.find(i => i.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const descriptionEN = textPart ? textPart.text.trim() : '';

const prev = $('Форс: есть ли черновик?').first().json;
return [{ json: { ...prev, descriptionEN } }];

function stripLabel(key) {
  return key.replace(/^[^a-zA-Z]+/, '');
}

function extractSection(text, tag) {
  if (!text) return '';
  const re = new RegExp('###' + tag + '###([\\s\\S]*?)###/' + tag + '###');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

// Те же 🖋-колонки, что и у художника (кроме SystemPrompt — у него своя,
// посекционная обработка), плюс 🎨 не нужны писателю (без картиночных референсов).
function collectByIcon(tmpl, icon) {
  const parts = [];
  for (const key of Object.keys(tmpl)) {
    if (key.includes('tmpl_SystemPrompt')) continue;
    if (key.includes(icon)) {
      const value = tmpl[key];
      if (value) parts.push(stripLabel(key) + ':\n' + value);
    }
  }
  return parts.join('\n\n');
}

const tmpl = $input.first().json;

const systemPromptKey = Object.keys(tmpl).find(k => k.includes('tmpl_SystemPrompt'));
const writerRoleNotes = extractSection(tmpl[systemPromptKey], 'ОПИСАНИЕ');
const sharedKnowledgeText = collectByIcon(tmpl, '🖋');
const writerKnowledgeText = (writerRoleNotes ? 'SystemPrompt (этап описания):\n' + writerRoleNotes + '\n\n' : '') + sharedKnowledgeText;

return [{ json: { writerKnowledgeText } }];

const trigger = $('Вход от диспетчера').first().json;
const project = $('Читаем строку проекта').first().json;
const context = $('Находим шаблон канала').first().json;

const writerRole = `Ты — редактор канала "${trigger.sheetName}", соавтор и собеседник автора канала. Сейчас идёт этап ОПИСАНИЯ: картинка уже согласована (она приложена к этому сообщению — посмотри на неё внимательно, это твой главный ориентир, а не просто текст промпта), и вместе с автором вы формулируете короткое тёплое описание этого момента. Говори свободно и живо, как обычный человек в разговоре — это не анкета и не чек-лист.\n\nКонтекст всего процесса, чтобы ты видела общую картину: выпуск видео проходит через три последовательных этапа — Картинка (уже пройдена), Описание (это сейчас твой этап), Техническая часть (заголовок, оверлей, хэштеги, теги, технический подвал). Пока Техчасть ждёт своей очереди — тебе не нужно ничего за неё додумывать.\n\nУ тебя есть два инструмента (function tools):\n- save_description_draft — вызывай каждый раз, когда предлагаешь автору конкретный, готовый к прочтению вариант текста описания (даже черновой) — это просто сохраняет текущий вариант, не финализирует ничего, можно вызывать сколько угодно раз в процессе поиска.\n- approve_description — вызывай это вместе с теми же словами, которыми ты сообщаешь автору, что текст согласован и финален. Передавай ОБА текста: finalText — русский, тот, что вы обсуждали, и finalTextEN — твой собственный точный перевод на английский (канал публикуется на YouTube по-английски, автор сверяет перевод в момент согласования, поэтому переводи внимательно и живо, не дословно-механически). Если ты произносишь слова о согласовании, но не вызываешь инструмент в тот же момент, получается недоразумение: по твоим словам всё готово, а по факту в таблице ничего не изменилось. Дело не в том, чтобы меньше говорить, быть суше или спешить с решением — оставайся такой же живой и свободной в разговоре, сколько угодно кружи, шути, предлагай варианты, возвращайся назад. Просто в тот самый момент, когда ты произносишь финальное решение вслух — пусть это решение долетит и до таблицы, не только до собеседника.\n- update_communication_notes — как и на этапе картинки: короткие, редкие заметки про стиль общения или неоднозначности в правилах, если правда есть чему научиться.\n\nБаза канала (персонаж, локации, стиль, миссия — используй по смыслу подписи каждого блока):\n${context.writerKnowledgeText}`;

return [{
  json: {
    conversationId: (function () {
      if (project.sys_ConversationId) return project.sys_ConversationId;
      try { return $('Сохраняем ID разговора (писатель)').first().json.conversationId; } catch (e) { return ''; }
    })(),
    pendingCallId: project.sys_ConversationId ? (project.sys_PendingToolCallId || '') : '', // pending-вызов имеет смысл только если разговор уже существовал
    systemPrompt: writerRole,
    userMessage: trigger.messageText,
    approvedImageUrl: project.ai_ApprovedImageUrl,
    projectId: trigger.projectId,
    chatId: trigger.chatId,
    sheetName: trigger.sheetName,
    channelKey: trigger.channelKey,
  }
}];

const response = $input.first().json;
const output = response.output || [];

const messageItem = output.find(item => item.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const plainText = textPart ? textPart.text : '';

const callItem = output.find(item => item.type === 'function_call');

let action = 'chat';
let messageToUser = plainText;
let draftText = '';
let finalText = '';
let finalTextEN = '';
let communicationNotes = '';
let callId = null;
let functionName = null;

if (callItem) {
  callId = callItem.call_id;
  functionName = callItem.name;
  let args = {};
  try { args = JSON.parse(callItem.arguments || '{}'); } catch (e) {}
  messageToUser = args.messageToUser || plainText || '';

  if (functionName === 'save_description_draft') {
    action = 'draft';
    draftText = args.text || '';
  } else if (functionName === 'approve_description') {
    action = 'approved';
    finalText = args.finalText || '';
    finalTextEN = args.finalTextEN || '';
  } else if (functionName === 'update_communication_notes') {
    communicationNotes = args.notes || '';
  }
}

const prep = $('Готовим запрос писателю').first().json;

return [{
  json: {
    action,
    messageToUser,
    draftText,
    finalText,
    finalTextEN,
    communicationNotes,
    callId,
    functionName,
    conversationId: prep.conversationId,
    projectId: prep.projectId,
    chatId: prep.chatId,
    sheetName: prep.sheetName,
    channelKey: prep.channelKey,
  }
}];

