// Тот же предохранитель, что у Техчасти: не разрешаем поставить финальный
// статус, пока обязательные поля пустые — независимо от того, что сказала модель.
const j = $input.first().json;
const required = {
  finalText: j.finalText,
  finalTextEN: j.finalTextEN,
};
const missingFields = Object.keys(required).filter(key => !required[key] || !String(required[key]).trim());
return [{ json: { ...j, missingFields } }];

