  }
}];

const req = $('Готовим запрос писателю').first().json;
const parsed = $('Парсим ответ писателя').first().json;

return [{
  json: {
    classifierInput: `Автор написал: "${req.userMessage}"\n\nРедактор ответил: "${parsed.messageToUser}"`,
  }
}];

const response = $input.first().json;
const output = response.output || [];
const messageItem = output.find(i => i.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const raw = (textPart ? textPart.text : '').trim().toLowerCase();
const isApproved = raw.startsWith('true');

const parsed = $('Парсим ответ писателя').first().json;
return [{ json: { ...parsed, isApproved } }];

